-- ==============================================================================
-- Semilla Canónica Idempotente y No Destructiva
-- Proyecto: El Huarique de Catacaos — Sistema POS
-- ==============================================================================

BEGIN;

-- 1. Restaurante Principal Canónico
VALUES (
    '00000000-0000-0000-0000-000000000001',
    'El Huarique de Catacaos',
    'Restaurante Turístico El Huarique de Catacaos S.A.C.',
    true
)
ON CONFLICT (id) DO NOTHING;

-- 2. Los 3 Salones Oficiales
ON CONFLICT (id) DO NOTHING;

-- 3. Las 80 Mesas Exactas (Distribución 30 / 25 / 25)
DO $$
DECLARE
    i integer;
    v_table_id uuid;
BEGIN
    -- Salón Principal (Mesas 1 a 30)
    FOR i IN 1..30 LOOP
        v_table_id := ('00000000-0000-0000-0002-' || lpad(i::text, 12, '0'))::uuid;
        VALUES (
            v_table_id,
            '00000000-0000-0000-0000-000000000001',
            '00000000-0000-0000-0001-000000000001',
            i,
            CASE WHEN i % 2 = 0 THEN 4 ELSE 6 END,
            'free',
            (i - 1) % 6 * 100,
            (i - 1) / 6 * 100
        )
        ON CONFLICT (id) DO NOTHING;
    END LOOP;

    -- Salón Familiar (Mesas 31 a 55)
    FOR i IN 31..55 LOOP
        v_table_id := ('00000000-0000-0000-0002-' || lpad(i::text, 12, '0'))::uuid;
        VALUES (
            v_table_id,
            '00000000-0000-0000-0000-000000000001',
            '00000000-0000-0000-0001-000000000002',
            i,
            CASE WHEN i % 3 = 0 THEN 8 ELSE 4 END,
            'free',
            (i - 31) % 5 * 100,
            (i - 31) / 5 * 100
        )
        ON CONFLICT (id) DO NOTHING;
    END LOOP;

    -- Salón Terraza (Mesas 56 a 80)
    FOR i IN 56..80 LOOP
        v_table_id := ('00000000-0000-0000-0002-' || lpad(i::text, 12, '0'))::uuid;
        VALUES (
            v_table_id,
            '00000000-0000-0000-0000-000000000001',
            '00000000-0000-0000-0001-000000000003',
            i,
            CASE WHEN i % 2 = 0 THEN 6 ELSE 4 END,
            'free',
            (i - 56) % 5 * 100,
            (i - 56) / 5 * 100
        )
        ON CONFLICT (id) DO NOTHING;
    END LOOP;
END $$;

